+ * @throws {RangeError} when the value is not a positive integer
+ */
+function assertPositiveInteger(value, name) {
+  if (!Number.isInteger(value) || value <= 0) {
+    throw new RangeError(`${name} must be a positive integer, received: ${String(value)}`);
+  }
+  return value;
+}
+
+/**
+ * Slice `items` into the requested one-based page.
+ *
+ * The returned array is always a copy, so mutating it never affects the input.
+ * A `page` beyond the last page is not an error: it yields an empty `items`
+ * array while still reporting the real `total` and `pageCount`.
+ *
+ * @param {ArrayLike<unknown>} items source collection to paginate
+ * @param {number} page one-based page number
+ * @param {number} pageSize number of entries per page
+ * @returns {{items: Array<unknown>, total: number, pageCount: number}} page slice plus totals
+ * @throws {RangeError} when `page` or `pageSize` is not a positive integer
+ */
+export function paginate(items, page, pageSize) {
+  assertPositiveInteger(page, 'page');
+  assertPositiveInteger(pageSize, 'pageSize');
+
+  const source = items ?? [];
+  const total = source.length ?? 0;
+  const pageCount = total === 0 ? 0 : Math.ceil(total / pageSize);
+  const start = (page - 1) * pageSize;
+
+  return { items: Array.prototype.slice.call(source, start, start + pageSize), total, pageCount };
+}

